INSERT INTO edfi.descriptor (Namespace, CodeValue, shortDescription, Description) values ('uri://njsmart.org/entryTypeDescriptor','E1G43','Original entry for the United States','A student, who for the first time in the United States or its outlying areas, enters any public or nonpublic elementary or secondary school.');
INSERT INTO edfi.descriptor (Namespace, CodeValue, shortDescription, Description) values ('uri://njsmart.org/entryTypeDescriptor','R1','Re-entry from within the same school','A student received from another class within the same school in which the student was previously entered in a different register regardless or program type.');
INSERT INTO edfi.descriptor (Namespace, CodeValue, shortDescription, Description) values ('uri://njsmart.org/entryTypeDescriptor','R10','Re-entry from an institution','Re-entry from an institution for treatment of a physical, mental or emotional disability-A student returning to the regular register after receiving individual instruction in an institution.');
INSERT INTO edfi.descriptor (Namespace, CodeValue, shortDescription, Description) values ('uri://njsmart.org/entryTypeDescriptor','R11','Re-entry after requesting a transfer but not attending another school','Re-entry after requesting a transfer but never having attended another school-A student returning to the regular register after being recorded as a transfer but who did not actually attend the new school. This code should only be used if the last entry for the student in the register was a transfer code.');
INSERT INTO edfi.descriptor (Namespace, CodeValue, shortDescription, Description) values ('uri://njsmart.org/entryTypeDescriptor','R12','Re-entry from parental instruction','A student returning to the regular register from parental instruction.');
INSERT INTO edfi.descriptor (Namespace, CodeValue, shortDescription, Description) values ('uri://njsmart.org/entryTypeDescriptor','R13','Re-entry from charter school','A student returning to the resident district from a charter school.');
INSERT INTO edfi.descriptor (Namespace, CodeValue, shortDescription, Description) values ('uri://njsmart.org/entryTypeDescriptor','R14','Re-entry from choice school','A student returning to the resident district from a choice school.');
INSERT INTO edfi.descriptor (Namespace, CodeValue, shortDescription, Description) values ('uri://njsmart.org/entryTypeDescriptor','R2','Re-entry from a public school within the district','A student who was previously enrolled in another public school within the same district.');
INSERT INTO edfi.descriptor (Namespace, CodeValue, shortDescription, Description) values ('uri://njsmart.org/entryTypeDescriptor','R3','Re-entry from a nonpublic school in the state','A student who was previously enrolled and attended a nonpublic school in the state.');
INSERT INTO edfi.descriptor (Namespace, CodeValue, shortDescription, Description) values ('uri://njsmart.org/entryTypeDescriptor','R4','Re-entry from another public school within the state','A student who was previously enrolled in another public school outside the district.');
INSERT INTO edfi.descriptor (Namespace, CodeValue, shortDescription, Description) values ('uri://njsmart.org/entryTypeDescriptor','R5','Re-entry from the same class in the same school','A student who returns to the same register after officially leaving due to expulsion or after dropping out of school and who has not been enrolled in any other school or program of instruction during the intervening period. This code should be used when the last code for the student was a dropout code. This includes students who drop out for a physical, mental or emotional disability who do not receive home instruction or individual instruction from a state or county institution.');
INSERT INTO edfi.descriptor (Namespace, CodeValue, shortDescription, Description) values ('uri://njsmart.org/entryTypeDescriptor','R6','Re-entry from a school in another state','A student received directly from a public or nonpublic school in another state.');
INSERT INTO edfi.descriptor (Namespace, CodeValue, shortDescription, Description) values ('uri://njsmart.org/entryTypeDescriptor','R7','Re-entry from another country','A student received directly from a school in another country having previously been a student in a school in the United States or the outlying areas.');
INSERT INTO edfi.descriptor (Namespace, CodeValue, shortDescription, Description) values ('uri://njsmart.org/entryTypeDescriptor','R9','Re-entry from a state or county institution for incarceration','A student returning to the regular register after receiving individual instruction in a state or county institution.');
INSERT INTO edfi.descriptor (Namespace, CodeValue, shortDescription, Description) values ('uri://njsmart.org/exitWithdrawTypeDescriptor','D1','Expulsion by the board of education','A student who is ordered to leave school based on a legal action by the board of education.');
INSERT INTO edfi.descriptor (Namespace, CodeValue, shortDescription, Description) values ('uri://njsmart.org/exitWithdrawTypeDescriptor','D10','Not of legal school age','A preschool student is no longer attending school because of a preschool handicap declassification or a child whose age is below the compulsory attendance age ceases to attend for any reason.');
INSERT INTO edfi.descriptor (Namespace, CodeValue, shortDescription, Description) values ('uri://njsmart.org/exitWithdrawTypeDescriptor','D11','Reached maximum age','A student cannot continue his/her education in a public school for the following school year if they have reached the age of 21.');
INSERT INTO edfi.descriptor (Namespace, CodeValue, shortDescription, Description) values ('uri://njsmart.org/exitWithdrawTypeDescriptor','D3','Dropout: Physical, mental or emotional disability','A student who ceases to attend due to a physical, mental or emotional disability who is not transferring to a state or county institution for individual instruction in order to continue or complete the prescribed program of studies for graduation.');
INSERT INTO edfi.descriptor (Namespace, CodeValue, shortDescription, Description) values ('uri://njsmart.org/exitWithdrawTypeDescriptor','D4','Dropout: Dissatisfied with school','A student who ceases to attend because of a behavioral or academic difficulty before completing the prescribed program of studies for graduation. The reasons include difficult student/staff relationships, lack of appropriate curriculum, or dislike of one or more aspects of the school experience.');
INSERT INTO edfi.descriptor (Namespace, CodeValue, shortDescription, Description) values ('uri://njsmart.org/exitWithdrawTypeDescriptor','D5','Dropout: Economic necessity and/or entered employment','A student who ceases to attend school for economic or employment reasons before completing the prescribed program of studies for graduation. The reasons may be one or more of the following: needed at home, encouraged by parents to leave school, inability to pay expenses associated with school attendance, seeking employment or had accepted employment.');
INSERT INTO edfi.descriptor (Namespace, CodeValue, shortDescription, Description) values ('uri://njsmart.org/exitWithdrawTypeDescriptor','D6','Dropout: Married and/or pregnant','A student who ceases to attend because of marriage or pregnancy before completing the prescribed program of students for graduation.');
INSERT INTO edfi.descriptor (Namespace, CodeValue, shortDescription, Description) values ('uri://njsmart.org/exitWithdrawTypeDescriptor','D7','Dropout: New residence, school status unknown','A student who requested a transfer to a new school for relocation to a new residence but whose school status is unknown because the student did not attend the new school.');
INSERT INTO edfi.descriptor (Namespace, CodeValue, shortDescription, Description) values ('uri://njsmart.org/exitWithdrawTypeDescriptor','D8','Dropout: Reason Unknown','A student who ceases to attend, is absent for more than ten days and whose whereabouts and school status is unknown.');
INSERT INTO edfi.descriptor (Namespace, CodeValue, shortDescription, Description) values ('uri://njsmart.org/exitWithdrawTypeDescriptor','D9','Death of a student.','Death of a student.');
INSERT INTO edfi.descriptor (Namespace, CodeValue, shortDescription, Description) values ('uri://njsmart.org/exitWithdrawTypeDescriptor','L','Graduation','The code is used to officially remove a student from the register because the required program of instruction for graduation has been completed. This code only applies to students graduating from High School.');
INSERT INTO edfi.descriptor (Namespace, CodeValue, shortDescription, Description) values ('uri://njsmart.org/exitWithdrawTypeDescriptor','PPE','Parentally Placed Exited','This code is used for a student who was parentally placed in a sectarian or non');
INSERT INTO edfi.descriptor (Namespace, CodeValue, shortDescription, Description) values ('uri://njsmart.org/exitWithdrawTypeDescriptor','T1','Transfer within the same school','A student to another register regardless of program type within the same school.');
INSERT INTO edfi.descriptor (Namespace, CodeValue, shortDescription, Description) values ('uri://njsmart.org/exitWithdrawTypeDescriptor','T2','Transfer to another public school or class within the district','A student transferred to any other public school or class within the same district.');
INSERT INTO edfi.descriptor (Namespace, CodeValue, shortDescription, Description) values ('uri://njsmart.org/exitWithdrawTypeDescriptor','T3','Transfer to a nonpublic school within the state','A student transferred to a nonpublic school within the state.');
INSERT INTO edfi.descriptor (Namespace, CodeValue, shortDescription, Description) values ('uri://njsmart.org/exitWithdrawTypeDescriptor','T4','Transfer to any public school outside the district','A student transferred to any other public school outside the district and within the state.');
INSERT INTO edfi.descriptor (Namespace, CodeValue, shortDescription, Description) values ('uri://njsmart.org/exitWithdrawTypeDescriptor','T6','Transfer to a Juvenile Justice Commission','Transfer to a Juvenile Justice Commission (not including Juvenile Detention Centers) or Department of Corrections institution for incarceration where individual instruction will be provided by the institution.');
INSERT INTO edfi.descriptor (Namespace, CodeValue, shortDescription, Description) values ('uri://njsmart.org/exitWithdrawTypeDescriptor','T7','Transfer to a Department of Children and Families institution.','Transfer to a Department of Children and Families institution for treatment of a physical, mental or emotional disability where individual instruction will be provided by the institution.');
INSERT INTO edfi.descriptor (Namespace, CodeValue, shortDescription, Description) values ('uri://njsmart.org/exitWithdrawTypeDescriptor','T8','Transfer out of the state or country','A student transferred to a public or nonpublic school or institution out of the state or country.');
INSERT INTO edfi.descriptor (Namespace, CodeValue, shortDescription, Description) values ('uri://njsmart.org/exitWithdrawTypeDescriptor','T9','Transfer to parental instruction','A student transferred to an equivalent program of instruction provided by parents.');
INSERT INTO edfi.descriptor (Namespace, CodeValue, shortDescription, Description) values ('uri://njsmart.org/exitWithdrawTypeDescriptor','TA','Transfer to alternative adult education for high school diploma','The student must be 20 years of age or younger.');
INSERT INTO edfi.descriptor (Namespace, CodeValue, shortDescription, Description) values ('uri://njsmart.org/exitWithdrawTypeDescriptor','TC','Transfer to charter school','A student transferred to charter school upon official notification of attendance.');
INSERT INTO edfi.descriptor (Namespace, CodeValue, shortDescription, Description) values ('uri://njsmart.org/exitWithdrawTypeDescriptor','TD','Transfer to choice school','A student transferred to an approved choice school.');
INSERT INTO edfi.descriptor (Namespace, CodeValue, shortDescription, Description) values ('uri://njsmart.org/exitWithdrawTypeDescriptor','TP','Transfer to a private facility.','A student transferred to a private facility where individual instruction is provided by the facility.');
INSERT INTO edfi.descriptor (Namespace, CodeValue, shortDescription, Description) values ('uri://njsmart.org/exitWithdrawTypeDescriptor','TR','Transfer to a renaissance school','A student transferred to a renaissance school upon official notice of attendance.');
