INSERT INTO edfi.descriptor (Namespace, CodeValue, shortDescription, Description) values ('uri://njsmart.org/FederalHSMathTestingReqDescriptor','E','Student took Algebra I, Geometry, and Algebra II in middle school','Student took Algebra I, Geometry, and Algebra II in middle school and took a more');
